/**
 * TypeScript face of the Rust aligner (crates/aligner → wasm via `bun run build:wasm`).
 *
 *   const { parseScript, createAligner } = await loadAligner()
 *   const aligner = createAligner(text)
 *   recognizer.on('result', (r) => render(aligner.feed(r.text, r.isFinal)))
 *
 * The wasm module is initialized once and shared. Everything runs on-device.
 */
import type { AlignResult, ParsedScript, ScriptAligner } from '../core/contracts'
// @ts-ignore -- generated by `bun run build:wasm` into a gitignored folder; typed by GeneratedAligner below.
import * as generated from './generated/aligner/aligner.js'

/** What we use from the wasm-bindgen output (kept local so a fresh checkout still type-checks). */
interface WasmAligner {
  readonly wordCount: number
  readonly reason: string
  feed(text: string, isFinal: boolean): AlignResult
  setCursor(wi: number): void
  free(): void
}

/** Accepted by wasm-bindgen's init: a URL/path, a Response, raw bytes, or a compiled module. */
export type AlignerWasmSource =
  | string
  | URL
  | Request
  | Response
  | BufferSource
  | WebAssembly.Module
  | Promise<Response | BufferSource | WebAssembly.Module>

interface GeneratedAligner {
  default(input?: { module_or_path?: AlignerWasmSource }): Promise<unknown>
  /** ParsedScript as JSON: one string across the boundary beats 10k objects. */
  parseScriptJson(text: string): string
  Aligner: new (script: string) => WasmAligner
}

export interface AlignerModule {
  parseScript(text: string): ParsedScript
  createAligner(text: string): ScriptAligner & { readonly reason: string }
}

const wasm = generated as unknown as GeneratedAligner
let ready: Promise<AlignerModule> | null = null

/**
 * Initialize the aligner wasm (once) and return the API.
 * In the browser call it with no argument; Vite resolves the .wasm next to the glue.
 * In Node/tests pass the bytes: `loadAligner(readFileSync(wasmPath))`.
 */
export function loadAligner(source?: AlignerWasmSource): Promise<AlignerModule> {
  if (!ready) {
    ready = wasm
      .default(source === undefined ? undefined : { module_or_path: source })
      .then(() => ({ parseScript: (text: string) => JSON.parse(wasm.parseScriptJson(text)) as ParsedScript, createAligner }))
    ready.catch(() => {
      ready = null // allow a retry after a failed fetch
    })
  }
  return ready
}

function createAligner(text: string): ScriptAligner & { readonly reason: string } {
  let inner: WasmAligner | null = new wasm.Aligner(text)
  const wordCount = inner.wordCount
  const live = (): WasmAligner => {
    if (!inner) throw new Error('aligner used after dispose()')
    return inner
  }
  return {
    wordCount,
    /** Why the last feed decided what it did (diagnostics overlay). */
    get reason() {
      return inner ? inner.reason : 'disposed'
    },
    feed: (speech: string, isFinal: boolean): AlignResult => live().feed(speech, isFinal),
    setCursor: (wordIndex: number) => live().setCursor(Math.trunc(wordIndex)),
    dispose: () => {
      inner?.free()
      inner = null
    },
  }
}
